  insert into public.lessons(unit_id,slug,title,skill,summary,sort_order,published)
  values (v_unit,'starter-u01-grammar-present-simple-frequency','Present simple and how often','Grammar','Use the present simple and adverbs of frequency for routines.',2,false)
  on conflict (slug) do update set unit_id=excluded.unit_id, title=excluded.title, skill=excluded.skill, summary=excluded.summary, sort_order=excluded.sort_order, updated_at=now() returning id into v_lesson;
  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Grammar","rule":"Use the present simple for habits, routines and facts.\n• I / you / we / they + base verb: I walk to class.\n• He / she / it + verb + -s/-es: She walks. He watches. It goes.\n• Verbs ending in consonant + y change to -ies: study → studies.\n\nAdverbs of frequency say how often: always (100%) – usually – often – sometimes – rarely – never (0%).\n• They go BEFORE the main verb: I often study at night.\n• They go AFTER the verb ''be'': She is always on time.\n\nGhi nhớ: trạng từ tần suất đứng trước động từ thường, nhưng đứng sau ''be''.","example":"My sister usually catches the bus, but she is never late for work.","figure":{"url":"","alt":""}}'::jsonb)
