  -- Writing: Describe your weekday routine
  insert into public.lessons(unit_id,slug,title,skill,summary,sort_order,published)
  values (v_unit,'starter-u01-writing-my-routine','Describe your weekday routine','Writing','Write 60–80 words about a normal weekday.',5,false)
  on conflict (slug) do update set unit_id=excluded.unit_id, title=excluded.title, skill=excluded.skill, summary=excluded.summary, sort_order=excluded.sort_order, updated_at=now() returning id into v_lesson;
  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Writing","prompt":"Write 60–80 words describing a normal weekday in your life. Say what you do in the morning, afternoon and evening, and use at least three adverbs of frequency (always, usually, often, sometimes, rarely, never).","minWords":60,"modelAnswer":"On weekdays I usually get up at six and have breakfast with my parents. I always catch the bus to college at seven because the roads are very busy later. My classes finish at twelve, so I often study in the library in the afternoon. In the evening I sometimes play badminton with my friends. After dinner I go online for a short time, and I rarely go to bed after eleven.","checklist":["Mention morning, afternoon and evening","Use the present simple correctly (he/she + -s)","Use at least three adverbs of frequency in the right position","Join ideas with and, but, so, because","Write 60–80 words"],"figure":{"url":"","alt":""}}'::jsonb)
  on conflict (lesson_id) do update set content=excluded.content, updated_at=now();

  -- Speaking: Talking about your day
  insert into public.lessons(unit_id,slug,title,skill,summary,sort_order,published)
