  on conflict (slug) do update set unit_id=excluded.unit_id, title=excluded.title, skill=excluded.skill, summary=excluded.summary, sort_order=excluded.sort_order, updated_at=now() returning id into v_lesson;
  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Speaking","prompt":"IELTS Speaking Part 1 – answer each question in 2–3 sentences:\n1. What is your favourite time of the day? Why?\n2. Do you usually have the same routine every day?\n3. How do you usually travel to school or work?\n4. Would you like to change anything about your daily routine?","preparationSeconds":15,"modelAnswer":"My favourite time of the day is the evening, because I finish my classes and I can relax. I usually have a similar routine on weekdays, but at the weekend I get up much later. I normally ride my motorbike to college; it takes about twenty minutes. If I could change one thing, I''d like to get up a little earlier so that I have time for breakfast.","checklist":["Answer the question directly first","Give a reason or an example (because…, for example…)","Use the present simple for habits","Speak for 15–25 seconds per question","Listen again: are there long pauses?"],"figure":{"url":"","alt":""}}'::jsonb)
