  values (v_question,0,'''Breakfast and dinner are usually included'' → hai bữa mỗi ngày.','Breakfast and dinner are usually included in the weekly price')
  on conflict (question_id) do update set correct_index=excluded.correct_index, explanation=excluded.explanation, evidence=excluded.evidence;
  insert into public.exercise_questions(lesson_id,slug,prompt,options,sort_order)
  values (v_lesson,'q3','Homestay families usually live close to the college. (True / False / Not Given)','["True","False","Not Given"]'::jsonb,2)
  on conflict (lesson_id,slug) do update set prompt=excluded.prompt, options=excluded.options, sort_order=excluded.sort_order returning id into v_question;
  insert into public.exercise_answer_keys(question_id,correct_index,explanation,evidence)
  values (v_question,1,'Bài đọc nói nhà thường ''a long way from the college'' → False.','houses are often a long way from the college')
  on conflict (question_id) do update set correct_index=excluded.correct_index, explanation=excluded.explanation, evidence=excluded.evidence;
  insert into public.exercise_questions(lesson_id,slug,prompt,options,sort_order)
  values (v_lesson,'q4','Private flats have the cheapest rent in the city. (True / False / Not Given)','["True","False","Not Given"]'::jsonb,3)
  on conflict (lesson_id,slug) do update set prompt=excluded.prompt, options=excluded.options, sort_order=excluded.sort_order returning id into v_question;
  insert into public.exercise_answer_keys(question_id,correct_index,explanation,evidence)
  values (v_question,2,'Chỉ nói căn hộ ''can be cheaper'' nếu chia tiền thuê, không so sánh với cả thành phố → Not Given.','they can be cheaper if the rent is divided between several flatmates')
  on conflict (question_id) do update set correct_index=excluded.correct_index, explanation=excluded.explanation, evidence=excluded.evidence;
  insert into public.exercise_questions(lesson_id,slug,prompt,options,sort_order)
  values (v_lesson,'q5','What is the minimum contract for a private flat?','["One month","Six months","One year"]'::jsonb,4)
  on conflict (lesson_id,slug) do update set prompt=excluded.prompt, options=excluded.options, sort_order=excluded.sort_order returning id into v_question;
  insert into public.exercise_answer_keys(question_id,correct_index,explanation,evidence)
  values (v_question,1,'''sign a contract for at least six months''.','sign a contract for at least six months')
  on conflict (question_id) do update set correct_index=excluded.correct_index, explanation=excluded.explanation, evidence=excluded.evidence;
  insert into public.exercise_questions(lesson_id,slug,prompt,options,sort_order)
  values (v_lesson,'q6','Which option is best for a student who wants to plan a budget easily?','["College halls","Homestay","Private flat"]'::jsonb,5)
